'use client';

import React from 'react';

/** Props for the {@link CodeBlock} component. */
export interface CodeBlockProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onCopy'> {
  /** Code string to display. */
  code: string;
  /** Programming language label. */
  language?: string;
  /** Whether to show line numbers. */
  lineNumbers?: boolean;
  /** Called when the copy button is clicked. Receives the code string. */
  onCopy?: (code: string) => void;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Code display with copy button and optional line numbers.
 * Renders a `<div>` with `sk-code-block`, a header with language label and copy button,
 * and a body with a `<pre><code>` block.
 */
export const CodeBlock = React.forwardRef<HTMLDivElement, CodeBlockProps>(
  ({ code, language, lineNumbers, onCopy, className, ...rest }, ref) => {
    const [copied, setCopied] = React.useState(false);

    const handleCopy = React.useCallback(() => {
      if (onCopy) {
        onCopy(code);
      } else if (typeof navigator !== 'undefined' && navigator.clipboard) {
        navigator.clipboard.writeText(code).catch(() => {});
      }
      setCopied(true);
      const timer = setTimeout(() => setCopied(false), 2000);
      return () => clearTimeout(timer);
    }, [code, onCopy]);

    const lines = lineNumbers ? code.split('\n') : null;

    return (
      <div
        ref={ref}
        className={`sk-code-block${className ? ` ${className}` : ''}`}
        data-line-numbers={lineNumbers ? '' : undefined}
        {...rest}
      >
        <div className="sk-code-block__header">
          {language && <span className="sk-code-block__lang">{language}</span>}
          <button
            className="sk-code-block__copy"
            data-copied={copied ? 'true' : undefined}
            onClick={handleCopy}
          >
            {copied ? 'copied' : 'copy'}
          </button>
        </div>
        <div className="sk-code-block__body">
          {lines && (
            <div className="sk-code-block__lines">
              {lines.map((_, i) => (
                <div key={i}>{i + 1}</div>
              ))}
            </div>
          )}
          <pre>
            <code>{code}</code>
          </pre>
        </div>
      </div>
    );
  },
);

CodeBlock.displayName = 'CodeBlock';

/**
 * skeehn — CodeBlock Component
 *
 * @component sk-code-block
 * @variants  default | terminal | diff
 * @states    [data-line-numbers] | [data-loading] | [data-skeleton] | [data-wrap]
 * @slots     __header | __lang | __meta | __copy | __body | __lines | __annotation
 * @features  Copy action, line numbers, highlighted lines, diff state, terminal chrome
 * @a11y      Focus-visible copy button, reduced motion, semantic pre/code blocks
 */

.sk-code-block {
  --sk-code-line-height: 1.7;
  --sk-code-bg: hsl(var(--sk-surface));

  position: relative;
  display: flex;
  flex-direction: column;
  overflow: clip;
  border: var(--sk-border);
  border-radius: var(--sk-radius-panel);
  background: var(--sk-panel-gradient);
  box-shadow: var(--sk-panel-shadow);
  font-family: var(--sk-font-mono);
  color: hsl(var(--sk-foreground));
  isolation: isolate;
}

.sk-code-block::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, hsl(var(--sk-background) / 0.4), transparent 32%),
    radial-gradient(circle at top right, hsl(var(--sk-foreground) / 0.05), transparent 40%);
  pointer-events: none;
  z-index: 0;
}

.sk-code-block > * {
  position: relative;
  z-index: 1;
}

.sk-code-block__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sk-space-3);
  padding: var(--sk-space-2) var(--sk-space-3);
  border-bottom: var(--sk-border);
  background:
    linear-gradient(180deg, hsl(var(--sk-muted) / 0.62), hsl(var(--sk-muted) / 0.36)),
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent 3px,
      hsl(var(--sk-foreground) / 0.02) 3px,
      hsl(var(--sk-foreground) / 0.02) 4px
    );
}

.sk-code-block__header-main {
  display: flex;
  align-items: center;
  gap: var(--sk-space-2);
  min-width: 0;
}

.sk-code-block__lang {
  font-size: var(--sk-font-size-xs);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: hsl(var(--sk-foreground));
}

.sk-code-block__meta {
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
  white-space: nowrap;
}

.sk-code-block__copy {
  display: inline-flex;
  align-items: center;
  gap: var(--sk-space-1);
  border: var(--sk-border);
  border-radius: var(--sk-radius-control);
  background: hsl(var(--sk-background) / 0.7);
  padding: var(--sk-space-1) var(--sk-space-2);
  font-size: var(--sk-font-size-xs);
  font-family: var(--sk-font-mono);
  color: hsl(var(--sk-muted-foreground));
  cursor: pointer;
  transition:
    border-color var(--sk-transition-fast),
    color var(--sk-transition-fast),
    background-color var(--sk-transition-fast),
    transform var(--sk-transition-fast);
}

.sk-code-block__copy:hover {
  color: hsl(var(--sk-foreground));
  border-color: hsl(var(--sk-foreground) / 0.35);
  background: hsl(var(--sk-background));
  transform: translateY(-1px);
}

.sk-code-block__copy:focus-visible {
  outline: none;
  border-color: hsl(var(--sk-ring));
  box-shadow: 0 0 0 2px hsl(var(--sk-ring) / 0.2);
}

.sk-code-block__copy[data-copied="true"] {
  border-color: hsl(var(--sk-success) / 0.35);
  color: hsl(var(--sk-success));
  background: hsl(var(--sk-success) / 0.12);
}

.sk-code-block__body {
  position: relative;
  overflow: auto;
  scrollbar-gutter: stable;
  padding: var(--sk-space-4);
  background: var(--sk-code-bg);
}

.sk-code-block__body::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-size: 32px 32px;
  opacity: calc(var(--sk-dither-opacity, 0.12) * 0.25);
  pointer-events: none;
}

.sk-code-block__body > * {
  position: relative;
  z-index: 1;
}

.sk-code-block pre {
  margin: 0;
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-code-line-height);
  tab-size: 2;
  white-space: pre;
  color: hsl(var(--sk-foreground));
}

.sk-code-block code {
  background: none;
  padding: 0;
  font: inherit;
}

.sk-code-block[data-wrap] pre {
  white-space: pre-wrap;
  word-break: break-word;
}

.sk-code-block[data-line-numbers] .sk-code-block__body {
  padding-left: calc(var(--sk-space-4) + 2.7rem);
}

.sk-code-block__lines {
  position: absolute;
  top: var(--sk-space-4);
  left: var(--sk-space-3);
  width: 2.1rem;
  font-size: var(--sk-font-size-xs);
  line-height: var(--sk-code-line-height);
  text-align: right;
  color: hsl(var(--sk-muted-foreground) / 0.58);
  user-select: none;
  pointer-events: none;
}

.sk-code-block__line {
  position: relative;
}

.sk-code-block__line[data-highlight="true"] {
  display: block;
  margin-inline: calc(var(--sk-space-2) * -1);
  padding-inline: var(--sk-space-2);
  border-left: 2px solid hsl(var(--sk-info) / 0.8);
  background: hsl(var(--sk-info) / 0.09);
}

.sk-code-inline {
  display: inline-block;
  border: var(--sk-border);
  border-radius: var(--sk-radius-control);
  padding: 0.12em 0.42em;
  font-family: var(--sk-font-mono);
  font-size: 0.86em;
  background: hsl(var(--sk-muted));
  color: hsl(var(--sk-foreground));
}

.sk-code-block[data-variant="diff"] .sk-code-line--added {
  display: block;
  margin-inline: calc(var(--sk-space-2) * -1);
  padding-inline: var(--sk-space-2);
  border-left: 3px solid hsl(var(--sk-success));
  background: hsl(var(--sk-success) / 0.12);
}

.sk-code-block[data-variant="diff"] .sk-code-line--removed {
  display: block;
  margin-inline: calc(var(--sk-space-2) * -1);
  padding-inline: var(--sk-space-2);
  border-left: 3px solid hsl(var(--sk-destructive));
  background: hsl(var(--sk-destructive) / 0.12);
  text-decoration: line-through;
  text-decoration-thickness: 1px;
  opacity: 0.78;
}

.sk-code-block[data-variant="diff"] .sk-code-line--context {
  opacity: 0.72;
}

.sk-code-block__annotation {
  display: block;
  margin-top: var(--sk-space-2);
  border-left: 2px solid hsl(var(--sk-info));
  background: hsl(var(--sk-info) / 0.07);
  padding: var(--sk-space-2) var(--sk-space-3);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-info));
}

.sk-code-block[data-variant="terminal"] {
  --sk-code-bg: hsl(0 0% 6%);

  border-color: hsl(var(--sk-success) / 0.3);
}

.sk-code-block[data-variant="terminal"] .sk-code-block__header {
  background:
    linear-gradient(180deg, hsl(0 0% 12%), hsl(0 0% 8%)),
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent 2px,
      hsl(0 0% 100% / 0.03) 2px,
      hsl(0 0% 100% / 0.03) 3px
    );
}

.sk-code-block[data-variant="terminal"] .sk-code-block__lang {
  color: hsl(var(--sk-success));
}

.sk-code-block[data-variant="terminal"] .sk-code-block__copy {
  background: hsl(0 0% 9%);
  border-color: hsl(var(--sk-success) / 0.28);
  color: hsl(var(--sk-success) / 0.88);
}

.sk-code-block[data-variant="terminal"] pre {
  color: hsl(var(--sk-success));
  text-shadow: 0 0 6px hsl(var(--sk-success) / 0.24);
}

.sk-code-block[data-variant="terminal"] .sk-code-block__body::before {
  background-image: var(--sk-dither-scanlines);
  background-size: 100% 3px;
  opacity: 0.15;
}

@keyframes sk-code-pulse-dither {
  0% {
    opacity: 0.04;
  }
  50% {
    opacity: 0.12;
  }
  100% {
    opacity: 0.04;
  }
}

@keyframes sk-code-shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.sk-code-block[data-loading] .sk-code-block__body::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  opacity: 0.08;
  animation: sk-code-pulse-dither 1.4s ease-in-out infinite;
  pointer-events: none;
}

.sk-code-block[data-skeleton] pre {
  color: transparent;
}

.sk-code-block[data-skeleton] .sk-code-block__body {
  min-height: 5.2rem;
  background: linear-gradient(
    90deg,
    hsl(var(--sk-muted)) 20%,
    hsl(var(--sk-accent)) 50%,
    hsl(var(--sk-muted)) 80%
  );
  background-size: 200% 100%;
  animation: sk-code-shimmer 1.6s ease-in-out infinite;
}

.sk-code-block__body::-webkit-scrollbar {
  height: 8px;
  width: 8px;
}

.sk-code-block__body::-webkit-scrollbar-thumb {
  background: hsl(var(--sk-border-color));
  border-radius: 999px;
}

.sk-code-block__body::-webkit-scrollbar-track {
  background: hsl(var(--sk-muted) / 0.5);
}

@media print {
  .sk-code-block {
    border: 1px solid hsl(var(--sk-foreground));
    box-shadow: none;
    break-inside: avoid;
  }

  .sk-code-block::before,
  .sk-code-block__body::before {
    display: none;
  }

  .sk-code-block__copy,
  .sk-code-block[data-skeleton] {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sk-code-block__copy {
    transition: none;
  }

  .sk-code-block__copy:hover {
    transform: none;
  }

  .sk-code-block[data-loading] .sk-code-block__body::after,
  .sk-code-block[data-skeleton] .sk-code-block__body {
    animation: none;
  }
}
